const BASE="https://syncsphere-hiv6.onrender.com";
const MAX=3, DELAY=400;
async function fr(url){let e;for(let i=0;i<MAX;i++){try{const r=await fetch(url,{method:"GET"});if(r.ok)return await r.json();e=new Error("HTTP "+r.status);}catch(x){e=x;}if(i<MAX-1)await new Promise(s=>setTimeout(s,DELAY*(i+1)));}throw e;}
(async()=>{
  for(let run=0;run<5;run++){
    const [c,cc]=await Promise.allSettled([fr(BASE+"/assignment/course-data"),fr(BASE+"/assignment/country-code")]);
    const cOk=c.status==="fulfilled", ccOk=cc.status==="fulfilled";
    console.log(`run ${run}: courses=${cOk? (Array.isArray(c.value)?c.value.length+" items":"bad-shape"):"FAILED"} country=${ccOk? cc.value.country_code:"FAILED"}`);
  }
})();
' 2>&1

